from solution import starts_one_ends
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(n):
    if n == 1:
        return 1
    return 18 * (10 ** (n - 2))


def brute(n):
    # Obviously-correct direct enumeration from spec wording.
    lo = 10 ** (n - 1) if n > 1 else 1
    hi = 10 ** n
    c = 0
    for i in range(lo, hi):
        s = str(i)
        assert len(s) == n
        if s[0] == '1' or s[-1] == '1':
            c += 1
    return c


def test_single_digit_is_one():
    assert starts_one_ends(1) == 1


def test_two_digits_is_18():
    assert starts_one_ends(2) == 18


def test_three_digits_is_180():
    assert starts_one_ends(3) == 180


def test_four_digits_is_1800():
    assert starts_one_ends(4) == 1800


def test_five_digits_is_18000():
    assert starts_one_ends(5) == 18000


@pytest.mark.parametrize("n,expected", [(1, 1), (2, 18), (3, 180), (4, 1800), (5, 18000), (6, 180000)])
def test_known_values(n, expected):
    assert starts_one_ends(n) == expected
    assert starts_one_ends(n) == reference(n)


@given(st.integers(min_value=1, max_value=6))
def test_property_matches_closed_form(n):
    assert starts_one_ends(n) == reference(n)


@given(st.integers(min_value=1, max_value=3))
def test_property_matches_brute_enumeration(n):
    assert starts_one_ends(n) == brute(n)


@given(st.integers(min_value=2, max_value=6))
def test_property_inclusion_exclusion(n):
    # start==1: 10**(n-1), end==1: 9*10**(n-2), both: 10**(n-2)
    start = 10 ** (n - 1)
    end = 9 * (10 ** (n - 2))
    both = 10 ** (n - 2)
    assert starts_one_ends(n) == start + end - both


@given(st.integers(min_value=2, max_value=5))
def test_property_times_ten_growth(n):
    # For n >= 2, count(n+1) == 10 * count(n)
    assert starts_one_ends(n + 1) == 10 * starts_one_ends(n)


def test_property_monotone_increasing():
    vals = [starts_one_ends(n) for n in range(1, 7)]
    for a, b in zip(vals, vals[1:]):
        assert b > a


def test_property_return_type_and_range():
    for n in range(1, 7):
        v = starts_one_ends(n)
        assert isinstance(v, int)
        assert 0 < v <= 9 * (10 ** (n - 1))


def test_property_total_bounds():
    # Union bound: max(start,end) <= count <= start+end
    for n in range(2, 7):
        v = starts_one_ends(n)
        start = 10 ** (n - 1)
        end = 9 * (10 ** (n - 2))
        assert max(start, end) <= v <= start + end


def test_large_n_scales():
    # Brute-force enumeration cannot satisfy this in time; closed form can.
    assert starts_one_ends(7) == 1800000
    assert starts_one_ends(10) == 1800000000
    assert starts_one_ends(15) == 18 * (10 ** 13)
